import os
import sys
import hashlib
import threading
import queue
from concurrent.futures import ThreadPoolExecutor, as_completed

def compute_digest(path):
    try:
        with open(path, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()
    except IOError as e:
        return f"error:{str(e)}"

def process_path(path, digest_queue, exit_queue):
    digest = compute_digest(path)
    digest_queue.put((digest, path))
    try:
        result = os.system(f"notify --digest {digest} --file {path}")
        exit_queue.put((path, result))
    except Exception as e:
        exit_queue.put((path, -1))

def main():
    if len(sys.argv) != 3:
        print("Usage: python digest_notify.py <file_path> <N>", file=sys.stderr)
        sys.exit(1)

    input_file = sys.argv[1]
    max_threads = int(sys.argv[2])

    with open(input_file, 'r') as f:
        paths = [line.strip() for line in f if line.strip()]

    digest_queue = queue.Queue()
    exit_queue = queue.Queue()

    with ThreadPoolExecutor(max_workers=max_threads) as executor:
        futures = []
        for path in paths:
            future = executor.submit(process_path, path, digest_queue, exit_queue)
            futures.append(future)

        for future in as_completed(futures):
            pass  # Wait for all tasks to complete

    while not digest_queue.empty():
        digest, path = digest_queue.get()
        print(f"DIGEST {path} {digest}")

    while not exit_queue.empty():
        path, exit_code = exit_queue.get()
        print(f"EXIT {path} {exit_code}")

if __name__ == "__main__":
    main()
